Reproduced against `main` (0d95a81), in a clean `node:20-alpine` container:

```js
const path = require('path');
const os = require('os');
const fs = require('fs');
os.homedir = () => '/root';

function loadFresh() {
  delete require.cache[require.resolve('/work/caveman/src/hooks/caveman-config.js')];
  return require('/work/caveman/src/hooks/caveman-config.js');
}

fs.mkdirSync('/root/.config/caveman', { recursive: true });
fs.writeFileSync('/root/.config/caveman/config.json', JSON.stringify({ defaultMode: 'lite' }));
delete process.env.XDG_CONFIG_HOME;

Object.defineProperty(process, 'platform', { value: 'win32' });
delete process.env.APPDATA;
let mod = loadFresh();
console.log('win32 getConfigDir():', mod.getConfigDir());
console.log('win32 getDefaultMode():', mod.getDefaultMode());

Object.defineProperty(process, 'platform', { value: 'linux' });
mod = loadFresh();
console.log('linux getConfigDir():', mod.getConfigDir());
console.log('linux getDefaultMode() (same file):', mod.getDefaultMode());
```

Output:

```
win32 getConfigDir(): /root/AppData/Roaming/caveman
win32 getDefaultMode(): full
linux getConfigDir(): /root/.config/caveman
linux getDefaultMode() (same file): lite
```

Same config file, same content, only `process.platform` differs. `getConfigDir()` (`src/hooks/caveman-config.js:28-39`) never checks the POSIX path on win32, and `getDefaultMode()` (line 105) has no fallback beyond it, so it silently drops to `'full'` with no signal that a config file exists just not on the active path.

Of the three fixes proposed above, option 1 (also check `~/.config/caveman/config.json` on win32 before falling through to `'full'`) is the smallest and fits the existing structure: `getDefaultMode()` already reads `readModeFromConfigFile()` once and returns on a hit, so a second call against the POSIX path as a win32-only fallback is a ~4-line change with no new resolution semantics on macOS/Linux. Option 2 (warn when a config exists at the "other" path) is worth adding alongside it since it also catches the inverse case (POSIX defaultMode changed but a stale APPDATA file still wins).

